using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

// Optional: override the OpenAI-compatible base URL (e.g. for Azure or local models)
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
            WebSearch.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("The web page URL to fetch")] string url) =>
            WebSearch.FetchPageAsync(url),
        "fetch_page",
        "Fetch the text content of a web page for deeper reading."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Body text of the note")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Save a research note. Use this to record important findings as you research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieve all research notes saved so far.")
};

// ---------------------------------------------------------------------------
// Chat client with automatic tool invocation
// ---------------------------------------------------------------------------
OpenAIClientOptions? clientOptions = baseUrl is not null
    ? new() { Endpoint = new Uri(baseUrl) }
    : null;

var openAiClient = clientOptions is not null
    ? new OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), clientOptions)
    : new OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey));

IChatClient chatClient = openAiClient
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var systemPrompt = $"""
    You are a research agent. Your goal is to thoroughly research the following topic
    and produce a well-structured summary.

    Topic: {topic}

    Instructions:
    1. Start by searching the web with several varied queries to get broad coverage.
    2. For the most promising results, fetch the full page to read deeper.
    3. Save important findings as notes using the save_note tool.
    4. After you have gathered enough information (aim for at least 3-5 notes),
       retrieve all your notes and write a final comprehensive summary.
    5. Your final message should be the polished summary — do NOT call any more tools
       after you begin writing the summary.

    Be thorough but concise. Cite sources where possible.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research this topic: {topic}")
};

var options = new ChatOptions { Tools = tools };

// Stream the final answer while letting the framework handle tool calls automatically
Console.ForegroundColor = ConsoleColor.Cyan;
await foreach (var update in chatClient.GetStreamingResponseAsync(messages, options))
{
    Console.Write(update.Text);
}
Console.ResetColor();

// Print saved notes summary
var notes = notebook.GetAll();
if (notes.Count > 0)
{
    Console.WriteLine($"\n\n📝 {notes.Count} research note(s) were saved during this session.");
}

Console.WriteLine();

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// ---------------------------------------------------------------------------
// Web Search Tool (uses DuckDuckGo HTML lite — no API key required)
// ---------------------------------------------------------------------------
static class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0 (compatible; bot)" }
        }
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            var results = ParseSearchResults(html);
            return results.Count == 0
                ? "No results found."
                : string.Join("\n\n", results.Select((r, i) => $"[{i + 1}] {r.Title}\n    {r.Url}\n    {r.Snippet}"));
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    public static async Task<string> FetchPageAsync(string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);
            // Crude tag stripping for plain-text extraction
            var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
            // Return first ~4000 chars to stay within token budgets
            return text.Length > 4000 ? text[..4000] + "…" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        // DuckDuckGo lite wraps each result in a <a class="result__a"> tag
        var linkPattern = new System.Text.RegularExpressions.Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            System.Text.RegularExpressions.RegexOptions.Singleline);
        var snippetPattern = new System.Text.RegularExpressions.Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            System.Text.RegularExpressions.RegexOptions.Singleline);

        var links = linkPattern.Matches(html);
        var snippets = snippetPattern.Matches(html);

        for (int i = 0; i < Math.Min(links.Count, 8); i++)
        {
            var rawUrl = links[i].Groups[1].Value;
            // DuckDuckGo wraps URLs in a redirect; extract the actual URL
            var udMatch = System.Text.RegularExpressions.Regex.Match(rawUrl, @"uddg=([^&]+)");
            var actualUrl = udMatch.Success
                ? Uri.UnescapeDataString(udMatch.Groups[1].Value)
                : rawUrl;

            var title = System.Text.RegularExpressions.Regex.Replace(
                links[i].Groups[2].Value, "<[^>]+>", "").Trim();
            var snippet = i < snippets.Count
                ? System.Text.RegularExpressions.Regex.Replace(
                    snippets[i].Groups[1].Value, "<[^>]+>", "").Trim()
                : "";

            results.Add(new SearchResult(title, actualUrl, snippet));
        }

        return results;
    }

    private record SearchResult(string Title, string Url, string Snippet);
}

